def find_maximized_capital_brute(k, w, profits, capital):
    n = len(profits)
    best = [w]

    def helper(remaining_k, cur_w, used):
        best[0] = max(best[0], cur_w)
        if remaining_k == 0:
            return
        for i in range(n):                                     # try every not-yet-used project
            if i not in used and capital[i] <= cur_w:
                helper(remaining_k - 1, cur_w + profits[i], used | {i})

    helper(k, w, frozenset())
    return best[0]

