#include <bits/stdc++.h>
using namespace std;

int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
    int n = profits.size();
    vector<pair<int,int>> projects(n);
    for (int i = 0; i < n; i++) projects[i] = {capital[i], profits[i]};
    sort(projects.begin(), projects.end());                          // sort by required capital
    priority_queue<int> maxHeap;
    int idx = 0;
    for (int round = 0; round < k; round++) {
        while (idx < n && projects[idx].first <= w) {                  // unlock newly affordable projects
            maxHeap.push(projects[idx].second);
            idx++;
        }
        if (maxHeap.empty()) break;
        w += maxHeap.top();                                              // take the highest-profit affordable project
        maxHeap.pop();
    }
    return w;
}
